constraints:
1 ≤ T ≤ 10^{3}
1 ≤ N ≤ 10^{12}

expected time complexity: O(log(n))
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def killinSpree(self, n):
		p = lambda n: n * (n + 1) * (2 * n + 1) // 6
		(lo, hi) = (0, n + 1)
		while lo < hi:
			mi = lo + (hi - lo) // 2
			if p(mi) > n:
				hi = mi
			else:
				lo = mi + 1
		return lo - 1
